import { LoadingOutlined } from '@ant-design/icons';
import {
  Alert,
  AutoComplete,
  Button,
  Collapse,
  Descriptions,
  Flex,
  Input,
  Table,
  Typography,
} from 'antd';
import { useState } from 'react';

import {
  type ColumnProfile,
  type ColumnProfileRequest,
  listColumns,
